func handleFormCancellation(w io.Writer, action string, err error) error {
	if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, huh.ErrTimeout) {
		fmt.Fprintf(w, "%s cancelled.\n", action)
		return nil
	}
	return fmt.Errorf("%s prompt failed: %w", action, err)
}

func (f *Form) run(ctx context.Context) error {
	var cancel context.CancelFunc
	if f.timeout > 0 {
		ctx, cancel = context.WithTimeout(ctx, f.timeout)
		defer cancel()
	}

	f.teaOptions = append(f.teaOptions, tea.WithContext(ctx))
	m, err := tea.NewProgram(
		compat.ViewModel{
			Model: f,
			ViewHook: func(v tea.View) tea.View {
				v.ReportFocus = true
				if f.viewHook == nil {
					return v
				}
				return f.viewHook(v)
			},
		},
		f.teaOptions...,
	).Run()
	if m.(compat.ViewModel).Model.(*Form).aborted || errors.Is(err, tea.ErrInterrupted) {
		return ErrUserAborted
	}
	if errors.Is(err, tea.ErrProgramKilled) {
		return ErrTimeout
	}
	if err != nil {
		return fmt.Errorf("huh: %w", err)
	}
	return nil
}

